import type { Metadata } from "next";
import Link from "next/link";

import { aboutsCol, coursesCol, successStoriesCol, usersCol } from "@/lib/collections";
import { preliminaryExamsCol } from "@/lib/collections";

export const metadata: Metadata = {
  title: "BJS Prep — Bangladesh Judicial Service Exam Preparation",
  description:
    "Structured, mentor-led preparation for the Bangladesh Judicial Service exam. Courses, model tests, and written evaluation.",
  openGraph: {
    title: "BJS Prep — Bangladesh Judicial Service Exam Preparation",
    description:
      "Structured, mentor-led preparation for the Bangladesh Judicial Service exam.",
    type: "website",
  },
};

export const revalidate = 60;

export default async function Home() {
  const [featuredCourses, userCount, publishedCourseCount, examCount, stories, aboutDoc] =
    await Promise.all([
      loadHomeData(
        "featured courses",
        async () =>
          (await coursesCol())
          .find({ isPublished: true, status: "published" })
          .sort({ order: 1, createdAt: -1 })
          .limit(3)
          .toArray(),
        [],
      ),
      loadHomeData("student count", async () => (await usersCol()).countDocuments(), 0),
      loadHomeData(
        "published course count",
        async () =>
          (await coursesCol()).countDocuments({ isPublished: true, status: "published" }),
        0,
      ),
      loadHomeData(
        "model test count",
        async () => (await preliminaryExamsCol()).countDocuments({ status: "published" }),
        0,
      ),
      loadHomeData(
        "success stories",
        async () =>
          (await successStoriesCol())
          .find({ status: "approved", isFeatured: true })
          .sort({ createdAt: -1 })
          .limit(4)
          .toArray(),
        [],
      ),
      loadHomeData("about content", async () => (await aboutsCol()).findOne({}), null),
    ]);

  const courses = featuredCourses;
  const storyList = stories;
  const aboutText = aboutDoc?.heroSubtitle ??
    "BJS Prep helps aspirants build disciplined legal exam preparation with mentor-led guidance, structured courses, and realistic practice tests.";

  return (
      <main className="mx-auto max-w-6xl px-4 py-8">
        <section className="rounded-2xl border border-border bg-card p-8 shadow-sm">
          <p className="text-sm font-medium uppercase tracking-[0.2em] text-accent">
            BJS Prep
          </p>
          <h1 className="mt-4 font-heading text-4xl font-bold text-primary md:text-5xl">
            Build a sharper prep routine.
          </h1>
          <p className="mt-4 max-w-2xl text-lg text-muted">
            {aboutText}
          </p>
          <div className="mt-6 flex flex-wrap gap-3">
            <Link href="/courses" className="rounded-md bg-primary px-5 py-3 text-sm font-medium text-cream">
              Explore courses
            </Link>
            <Link href="/model-tests" className="rounded-md border border-border px-5 py-3 text-sm font-medium text-primary">
              Practice model tests
            </Link>
          </div>
        </section>

        <section className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          <StatCard label="Students" value={String(userCount ?? 0)} />
          <StatCard label="Published courses" value={String(publishedCourseCount ?? 0)} />
          <StatCard label="Model tests" value={String(examCount ?? 0)} />
          <StatCard label="Attempts" value="0" />
        </section>

        <section className="mt-12">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="font-heading text-2xl font-bold text-primary">
              Featured courses
            </h2>
            <Link href="/courses" className="text-sm text-accent hover:underline">
              View all
            </Link>
          </div>

          {courses.length === 0 ? (
            <div className="rounded-lg border border-dashed border-border bg-card p-10 text-center text-muted">
              Courses will appear here soon.
            </div>
          ) : (
            <div className="grid gap-5 md:grid-cols-3">
              {courses.map((course) => (
                <article key={course._id.toString()} className="rounded-lg border border-border bg-card p-4 shadow-sm">
                  <div className="mb-4 h-32 rounded-md bg-primary/5" />
                  <p className="text-xs uppercase tracking-[0.2em] text-accent">
                    {course.category}
                  </p>
                  <h3 className="mt-2 text-lg font-semibold text-primary">
                    {course.title}
                  </h3>
                  <p className="mt-2 text-sm text-muted">{course.description}</p>
                  <div className="mt-4 flex items-center justify-between text-sm">
                    <span className="font-medium text-primary">
                      {course.price === 0 ? "Free" : `BDT ${course.price}`}
                    </span>
                    <span className="text-muted">{course.durationLabel}</span>
                  </div>
                </article>
              ))}
            </div>
          )}
        </section>

        <section className="mt-12">
          <h2 className="font-heading text-2xl font-bold text-primary">
            Success stories
          </h2>
          {storyList.length === 0 ? (
            <div className="mt-5 rounded-lg border border-dashed border-border bg-card p-10 text-center text-muted">
              Student stories will appear here soon.
            </div>
          ) : (
            <div className="mt-5 grid gap-5 md:grid-cols-2 xl:grid-cols-4">
              {storyList.map((story) => (
                <article key={story._id.toString()} className="rounded-lg border border-border bg-card p-5 shadow-sm">
                  <p className="text-sm leading-6 text-foreground">“{story.quote}”</p>
                  <p className="mt-4 text-sm font-medium text-primary">
                    {story.authorName ?? "Student"}
                  </p>
                </article>
              ))}
            </div>
          )}
        </section>
      </main>
  );
}

async function loadHomeData<T>(
  section: string,
  load: () => Promise<T>,
  fallback: T,
): Promise<T> {
  try {
    return await load();
  } catch (error) {
    console.error(`Home page ${section} data error`, error);
    return fallback;
  }
}

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg border border-border bg-card p-5 shadow-sm">
      <p className="text-xs uppercase tracking-[0.2em] text-muted">{label}</p>
      <p className="mt-2 font-heading text-3xl font-bold text-primary">{value}</p>
    </div>
  );
}
